export const requireAuth = (req, res, next) => {
  // 1. Read all cookies generated by cookie-parser
  console.log("Cookies received from Frontend:", req.cookies);

  // 2. Check if the specific login cookie exists
  const isLoggedIn = req.cookies.isLoggedIn;

  if (isLoggedIn === "true") {
    // 3. User is authenticated, let them access the controller!
    console.log("User successfully authenticated!");
    next();
  } else {
    // 4. No valid cookie found, stop the request and send a 401 error
    console.log("Authentication failed: No valid cookie.");
    return res.status(401).json({
      success: false,
      error: "Unauthorized: Please log in to access this resource",
    });
  }
};
